"""Tests of tools/ask.py on the notes of the graph.py fixture.

Run from the project root: ``.venv/bin/python -m pytest tools/tests``.
"""

import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import ask  # noqa: E402
from test_graph import run, valid_tables  # noqa: E402


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> dict:
    """Notes generated by graph.py from the valid fixture tables."""
    assert run(tmp_path, valid_tables()).returncode == 0
    monkeypatch.setattr(ask, "ROOT", tmp_path)
    return ask.load_notes()


def test_q6_rows(notes: dict) -> None:
    lines = ask.q6(notes).splitlines()
    rows = {line.split(" | ")[2]: line for line in lines[2:]}
    assert set(rows) == {"W100", "W200", "W300"}
    assert rows["W100"].startswith("| Article 80094 | relevant |")
    assert "q1 (openalex_work)" in rows["W100"]
    assert "cited by Article 80094" not in rows["W100"]
    assert rows["W300"].startswith("| candidate | excluded |")
    assert "q2 (openalex_search), q3 (openalex_links)" in rows["W300"]
    assert "cites Article 80094" in rows["W300"]
    # candidates first, relevant before excluded, admitted last
    assert [line.split(" | ")[2] for line in lines[2:]] == [
        "W200", "W300", "W100"]


def test_q6_empty(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    (tmp_path / "notes").mkdir()
    monkeypatch.setattr(ask, "ROOT", tmp_path)
    assert ask.q6(ask.load_notes()).startswith("No Source notes yet")
